/**
 * How Sendai bamboo and sparrows (`sendai-zasa`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/sendai-zasa";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"A ring of bamboo with sprays of leaves outside it and two sparrows inside, beak to beak. The ring is the band between two circles about the centre, open at the top between two lines ruled from the centre, with a white joint across it on each of two more and two short white lines of grain by each joint. In the opening is a knot: the star left between four circles of one width. Under the ring stand the cut ends of the two stalks, between upright lines, a joint across each. A thin stem runs round outside the ring, and on it are pairs of leaves, five a side, a twelfth of a turn apart, with one more leaf by each stalk's end; a leaf is the lens between two circles of one width, with a white vein down its middle. Each sparrow lies between a circle about a point on the axis and a wider circle struck from the other side. Round its head is a band of scales that are white dots, and then a white line; beyond it the white lines between the feathers of the wing and the tail are ruled from the head's centre to points three apart on a level line. The eye is a white disc with a dot, and the beak is ruled from its point by the axis. The ring is built first, then each pair of leaves where it stands, clockwise, then the right sparrow, and the left sparrow where it stands.","ja":"竹の輪の外に笹の葉を置き、中に二羽の雀を向かい合わせた紋です。輪は、中心のまわりの二つの円の間の帯です。上は、中心から引いた二本の直線の間をあけ、別の二本の直線の上に、白い節を入れ、節のそばに、短い白い線を二本ずつ入れます。あけた所には結び目を置きます。同じ幅の円四つの間に残る、先が四つの星の形です。輪の下には、二本の竹の切り口が、縦の直線の間に立ち、それぞれに節が一つあります。輪の外を細い茎が一周し、茎の上に、葉二枚の組を、片側に五つずつ、30度ずつ離して置き、竹の切り口のそばに、葉をもう一枚ずつ置きます。葉は、同じ幅の円二つが重なるレンズ形で、まん中に白い葉脈を一本通します。雀は、中心線の上の一点を中心とする円と、反対側から描いた広い円の間にあります。頭のまわりに、白い点を並べたうろこの帯があり、その外に白い線が一本あります。その外の、翼と尾の羽根の間の白い線は、頭の中心から、横の線の上に3ずつ離した点へ引いた直線です。目は点のある白い円で、くちばしは、中心線のそばの先から直線を引きます。輪を先に作図し、葉の組を時計回りに一つずつその場で作図し、右の雀を作図してから、左の雀をその場で作図します。"};

export default construction;
export { construction, description };
